package com.dexm.personajes.adapter.out.persistence;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="characters") public class CharacterEntity {
 @Id private String id; private String name; private String campaignId; @Column(name="image_url", columnDefinition="longtext") private String imageUrl; private int experience; private int level; private int evolutionPoints; private int geneticsPoints; @Column(nullable=false) private boolean closed; @Column(name="attributes_json", columnDefinition="text") private String attributesJson; @Column(name="genetics_json", columnDefinition="text") private String geneticsJson; private Instant createdAt; private Instant updatedAt;
 protected CharacterEntity(){} public CharacterEntity(String id,String name,int experience,String attributesJson,String geneticsJson){this(id,null,name,null,experience,1,attributesJson,geneticsJson);} public CharacterEntity(String id,String campaignId,String name,String imageUrl,int experience,String attributesJson,String geneticsJson){this(id,campaignId,name,imageUrl,experience,1,attributesJson,geneticsJson);} public CharacterEntity(String id,String campaignId,String name,String imageUrl,int experience,int level,String attributesJson,String geneticsJson){this.id=id;this.campaignId=campaignId;this.name=name;this.imageUrl=imageUrl;this.experience=experience;this.level=level;this.attributesJson=attributesJson;this.geneticsJson=geneticsJson;this.createdAt=Instant.now();this.updatedAt=this.createdAt;}
 public String getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getCampaignId(){return campaignId;} public String getImageUrl(){return imageUrl;} public void setImageUrl(String v){imageUrl=v;} public int getExperience(){return experience;} public void setExperience(int v){experience=v;} public int getLevel(){return level;} public void setLevel(int v){level=Math.max(1,v);} public int getEvolutionPoints(){return evolutionPoints;} public void setEvolutionPoints(int v){evolutionPoints=Math.max(0,v);} public int getGeneticsPoints(){return geneticsPoints;} public void setGeneticsPoints(int v){geneticsPoints=Math.max(0,v);} public boolean isClosed(){return closed;} public void setClosed(boolean v){closed=v;} public String getAttributesJson(){return attributesJson;} public void setAttributesJson(String v){attributesJson=v;} public String getGeneticsJson(){return geneticsJson;} public void setGeneticsJson(String v){geneticsJson=v;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} public void touch(){updatedAt=Instant.now();}
}
